public class Q25_Thread_Priorities { public static void main(String[] args){ for(int p:new int[]{Thread.MIN_PRIORITY,Thread.NORM_PRIORITY,Thread.MAX_PRIORITY}){final int priority=p;Thread t=new Thread(()->System.out.println(Thread.currentThread().getName()+" priority="+priority));t.setName("Priority-"+p);t.setPriority(p);t.start();} /* Priority does not guarantee execution order. */ } }
